window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-channels-widget.html"]="<!-- Settings: Widget Channel -->\n<style>\n.st-widget-toggle{display:flex;align-items:center;gap:12px;margin-bottom:20px}\n.toggle{width:44px;height:24px;border-radius:12px;background:#ccc;cursor:pointer;position:relative;transition:.2s}\n.toggle.on{background:var(--accent)}\n.toggle::after{content:'';position:absolute;top:2px;left:2px;width:20px;height:20px;border-radius:50%;background:#fff;transition:.2s}\n.toggle.on::after{left:22px}\n.st-embed{background:var(--nav);color:#a5b4fc;padding:16px;border-radius:var(--radius);font-family:monospace;font-size:12px;white-space:pre-wrap;word-break:break-all;max-height:200px;overflow:auto;margin-top:12px}\n.st-form label{display:block;font-size:13px;font-weight:500;margin-bottom:14px}\n.st-form label input{display:block;width:100%;padding:10px 12px;border:1px solid var(--border);border-radius:8px;margin-top:4px;font-size:14px;background:var(--bg)}\n.st-form label input:focus{outline:2px solid var(--accent);outline-offset:-1px}\n.st-color-row{display:flex;align-items:center;gap:10px}\n.st-color-row input[type=color]{width:48px;height:36px;border:1px solid var(--border);border-radius:8px;cursor:pointer;padding:2px}\n.st-color-row .color-hex{font-size:13px;font-weight:600;font-family:monospace}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\">\n    <div class=\"sn-title\">Organisasi</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-general')\">Umum</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-members')\">Anggota</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-roles')\">Role & Izin</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-tags')\">Tag</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-shift-hours')\">Jam Shift</div>\n    <div class=\"sn-title\">Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-assignments')\">Assignment</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-team-inbox')\">Tim Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-sla')\">SLA</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-csat')\">CSAT</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-macros')\">Makro</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-tickets')\">Tiket</div>\n    <div class=\"sn-title\">Channel</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-api')\">WhatsApp API</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-web')\">WhatsApp Web</div>\n    <div class=\"sn-item active\" onclick=\"go('settings/channels-widget')\">Widget</div>\n    <div class=\"sn-title\">Billing</div>\n    <div class=\"sn-item\" onclick=\"go('settings/billing-cost')\">Kontrol Biaya</div>\n    <div class=\"sn-title\">Developer</div>\n    <div class=\"sn-item\" onclick=\"go('settings/developer-webhook')\">Webhook</div>\n  </aside>\n\n  <div class=\"settings-body\">\n    <h2 style=\"margin-bottom:4px\">Chat Widget</h2>\n    <p style=\"font-size:13px;color:var(--muted);margin-bottom:20px\">Konfigurasi widget chat yang dipasang di website Anda.</p>\n\n    <div class=\"st-widget-toggle\">\n      <span style=\"font-size:13px;font-weight:600\">Widget Aktif</span>\n      <div class=\"toggle\" id=\"widgetToggle\" onclick=\"toggleWidget()\"></div>\n      <span style=\"font-size:12px;color:var(--muted)\" id=\"widgetStatusText\">-</span>\n    </div>\n\n    <div class=\"st-form card\" style=\"max-width:480px;padding:16px\">\n      <label>Domain Website<input id=\"widgetDomain\" placeholder=\"contoh.com\"></label>\n      <label>\n        Warna Widget\n        <div class=\"st-color-row\" style=\"margin-top:4px\">\n          <input type=\"color\" id=\"widgetColor\" onchange=\"document.getElementById('colorHex').textContent=this.value\">\n          <span class=\"color-hex\" id=\"colorHex\">#4f46e5</span>\n        </div>\n      </label>\n      <div style=\"display:flex;justify-content:flex-end\">\n        <button class=\"btn primary\" onclick=\"saveWidget()\">Simpan</button>\n      </div>\n    </div>\n\n    <h3 style=\"margin:24px 0 8px\">Kode Embed</h3>\n    <p style=\"font-size:12px;color:var(--muted);margin-bottom:8px\">Salin kode ini ke halaman website Anda:</p>\n    <div class=\"st-embed\" id=\"embedCode\"></div>\n    <button class=\"btn\" style=\"margin-top:8px\" onclick=\"copyEmbed()\">📋 Salin Kode</button>\n  </div>\n</div>\n\n<script>\n(function(){\n  const w=DB.settings.channels.widget;\n  const tog=document.getElementById('widgetToggle');\n  tog.className='toggle '+(w.enabled?'on':'');\n  document.getElementById('widgetStatusText').textContent=w.enabled?'Aktif':'Nonaktif';\n  document.getElementById('widgetDomain').value=w.domain||'';\n  document.getElementById('widgetColor').value=w.color||'#4f46e5';\n  document.getElementById('colorHex').textContent=w.color||'#4f46e5';\n  updateEmbed(w.domain,w.color);\n})();\n\nfunction updateEmbed(domain,color){\n  const code='<script src=\"https://cdn.satuinbox.id/widget.js\"><\\/script>\\n<script>\\n  SatuInbox.init({\\n    domain: \"'+(domain||'contoh.com')+'\",\\n    color: \"'+(color||'#4f46e5')+'\"\\n  });\\n<\\/script>';\n  document.getElementById('embedCode').textContent=code;\n}\n\nfunction toggleWidget(){\n  const w=DB.settings.channels.widget;\n  w.enabled=!w.enabled;\n  saveStore();\n  go('settings/channels-widget');\n}\n\nfunction saveWidget(){\n  const domain=document.getElementById('widgetDomain').value.trim();\n  const color=document.getElementById('widgetColor').value;\n  if(!domain){showToast('Domain wajib diisi');return}\n  DB.settings.channels.widget={...DB.settings.channels.widget,domain,color};\n  saveStore();\n  updateEmbed(domain,color);\n  showToast('Pengaturan widget berhasil disimpan');\n}\n\nfunction copyEmbed(){\n  navigator.clipboard.writeText(document.getElementById('embedCode').textContent);\n  showToast('Kode embed disalin');\n}\n</script>\n";
